```apex
public class ExchangeRateClient {

    /**
     * Domain exception used for every validation, callout and parsing failure.
     * Messages always carry enough context (e.g. the numeric HTTP status code)
     * to be actionable for Finance support.
     */
    public class ExchangeRateException extends Exception {
        public ExchangeRateException(String message) {
            super(message);
        }
    }

    private static final String NC_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    /**
     * Fetches live FX rates for the requested quote currencies relative to baseCurrency.
     *
     * @param  baseCurrency    base ISO code (trimmed/upper-cased to 3 letters A-Z)
     * @param  quoteCurrencies set of quote ISO codes to request
     * @return                 map of every requested (normalised) code to its rate
     * @throws ExchangeRateException when inputs are invalid, the callout does not
     *         return HTTP 200, or the response cannot be parsed / is missing a rate
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Validate & normalise all inputs BEFORE making any callout ---
        String base = normalise(baseCurrency, 'Base currency');

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must be provided and non-empty');
        }

        Set<String> requestedCodes = new Set<String>();
        for (String quote : quoteCurrencies) {
            requestedCodes.add(normalise(quote, 'Quote currency'));
        }

        // Deterministic, comma-separated symbols list (order is irrelevant to the API).
        List<String> orderedCodes = new List<String>(requestedCodes);
        Collections.sort(orderedCodes);
        String symbols = String.join(orderedCodes, ',');

        // --- Perform the callout, retrying exactly once on HTTP 503 ---
        HttpResponse response = sendRequest(base, symbols);
        if (response.getStatusCode() == 503) {
            response = sendRequest(base, symbols);
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + response.getStatusCode()
            );
        }

        // --- Parse the successful response ---
        return parseRates(response.getBody(), requestedCodes);
    }

    private static HttpResponse sendRequest(String base, String symbols) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(NC_ENDPOINT + '?base=' + base + '&symbols=' + symbols);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return new Http().send(request);
    }

    private static Map<String, Decimal> parseRates(String body, Set<String> requestedCodes) {
        Map<String, Decimal> rates = new Map<String, Decimal>();
        try {
            Map<String, Object> payload = (Map<String, Object>) JSON.deserializeUntyped(body);
            if (payload == null) {
                throw new ExchangeRateException('Exchange rate response body was empty');
            }

            Object ratesObj = payload.get('rates');
            if (!(ratesObj instanceof Map)) {
                throw new ExchangeRateException('Exchange rate response did not contain a "rates" object');
            }
            Map<String, Object> providerRates = (Map<String, Object>) ratesObj;

            // Only requested codes are returned; extra rates in the payload are ignored.
            for (String code : requestedCodes) {
                Object value = providerRates.get(code);
                if (value == null) {
                    throw new ExchangeRateException('No exchange rate was returned for currency ' + code);
                }
                rates.put(code, toDecimal(value, code));
            }
        } catch (ExchangeRateException domainException) {
            // Our own, already-descriptive errors bubble up unchanged.
            throw domainException;
        } catch (Exception genericException) {
            throw new ExchangeRateException(
                'Unable to parse exchange rate response: ' + genericException.getMessage()
            );
        }
        return rates;
    }

    private static Decimal toDecimal(Object value, String code) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        try {
            return Decimal.valueOf(String.valueOf(value));
        } catch (Exception invalidNumber) {
            throw new ExchangeRateException('Exchange rate for currency ' + code + ' is not a valid number');
        }
    }

    private static String normalise(String code, String label) {
        if (code == null) {
            throw new ExchangeRateException(label + ' must be provided');
        }
        String normalised = code.trim().toUpperCase();
        if (!normalised.matches('^[A-Z]{3}$')) {
            throw new ExchangeRateException(label + ' must be exactly three letters (A-Z): ' + code);
        }
        return normalised;
    }
}
