```apex
public class ErpAccountSyncJob implements Queueable {
    private final Set<Id> accountIds;
    private final Integer attempt;

    /**
     * @param accountIds IDs of the accounts to sync to the ERP.
     * @param attempt    1 for the first run; incremented on each retry.
     */
    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the transaction finalizer BEFORE doing any work so that the
        // outcome (success or failure) of this run is always logged.
        context.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        // Load the accounts and mark them as synced to the ERP.
        List<Account> accounts = [SELECT Id, Description FROM Account WHERE Id IN :accountIds];
        for (Account acc : accounts) {
            acc.Description = 'Synced to ERP';
        }

        // All-or-nothing save. The standard update DML statement is all-or-nothing:
        // if any account cannot be saved it throws a DmlException. We deliberately
        // do NOT catch it, so the whole job fails and none of its changes are kept.
        update accounts;
    }
}
