public with sharing class OpportunityRollupService {

    /**
     * Returns each requested account's closed-won revenue for the current
     * calendar year.
     *
     * <p>The value for an account is the sum of Opportunity.Amount over its
     * won opportunities (IsWon = true) whose CloseDate falls within the current
     * calendar year (Jan 1 - Dec 31 of the current year).</p>
     *
     * <ul>
     *   <li>Every requested account Id is a key in the returned map. Accounts
     *       with no qualifying opportunities, or whose qualifying opportunities
     *       all have a blank Amount, map to 0 - never null.</li>
     *   <li>Ids that were not requested are never keys.</li>
     *   <li>A null or empty input set returns an empty map.</li>
     * </ul>
     *
     * <p>Sums are computed in the database with a single aggregate SOQL query;
     * individual opportunity records are never loaded. SOQL runs in the context
     * of the running user, so only opportunities the user can see are summed.</p>
     *
     * @param accountIds The set of account Ids to roll up.
     * @return Map of account Id to won (closed-won) revenue for the current
     *         calendar year. Never contains null values.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> wonAmounts = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return wonAmounts;
        }

        // Seed every requested account with 0 so blanks map to 0, never null,
        // and so Ids with no qualifying opportunities remain present.
        for (Id accountId : accountIds) {
            wonAmounts.put(accountId, 0);
        }

        // Current calendar year bounds: Jan 1 through Dec 31 of the current year.
        Date startDate = Date.today().startOfYear();
        Date endDate = Date.today().endOfYear();

        // Single aggregate query grouped by account; the individual opportunity
        // records are never loaded into Apex.
        for (AggregateResult ar : [
            SELECT AccountId,
                   SUM(Amount) totalWonAmount
            FROM Opportunity
            WHERE IsWon = true
              AND AccountId IN :accountIds
              AND CloseDate >= :startDate
              AND CloseDate <= :endDate
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('totalWonAmount');

            // Defensive guard: only override requested accounts and treat a null
            // sum (e.g. all qualifying opportunities have blank Amount) as 0.
            if (accountId != null && wonAmounts.containsKey(accountId)) {
                wonAmounts.put(accountId, total == null ? 0 : total);
            }
        }

        return wonAmounts;
    }
}
