public class Opportunities extends fflib_SObjectDomain {

    protected Opportunities(List<SObject> au) {
        super(au);
    }

    public override void doTriggerHandler() {
        // Defaults are applied only when records are created (before insert),
        // never on update / delete / undelete.
        if (isInsert && isBefore) {
            applyCreateDefaults((List<Opportunity>) records);
        }
    }

    private void applyCreateDefaults(List<Opportunity> opportunities) {
        final Date defaultCloseDate = Date.today().addDays(30);
        for (Opportunity opp : opportunities) {
            // Keep any value that is already set; only default when null.
            if (opp.CloseDate == null) {
                opp.CloseDate = defaultCloseDate;
            }
            if (opp.Type == null) {
                opp.Type = 'New Customer';
            }
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Constructor() {}

        public fflib_SObjectDomain construct(List<SObject> au) {
            return new Opportunities(au);
        }
    }
}
