public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {
    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        final List<Schema.SObjectField> fieldList = getSObjectFieldList();
        fieldList.add(Opportunity.Account.Name);

        // The query factory is cached and shared on the selector, so build the
        // query and then restore its default state to avoid leaking the custom
        // fields/filter/order/limit into other selector methods.
        final fflib_SObjectQueryFactory queryFactory = getQueryFactory();
        final fflib_SObjectQuery query = queryFactory
            .setFields(fieldList)
            .setFilterClause('IsClosed = false AND AccountId IN :accountIds')
            .setOrderBy('Amount DESC NULLS LAST, CloseDate ASC')
            .setLimitValue(maxRecords)
            .getQuery();

        final List<Opportunity> opportunities = (List<Opportunity>) query.query();

        queryFactory
            .setFields(getSObjectFieldList())
            .setFilterClause(null)
            .setOrderBy(null)
            .setLimitValue(null);

        return opportunities;
    }
}
