```apex
public with sharing class CaseEscalationService {

    public class EscalationException extends Exception {
    }

    /**
     * Escalates the given cases: flags them, sets their priority, and creates
     * a follow-up task for each. All changes are committed through a single
     * unit of work.
     *
     * @param caseIds Set of Case ids to evaluate for escalation
     * @param reason  Reason for the escalation; used in the created task's subject
     */
    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate inputs before reading or writing anything.
        if (String.isBlank(reason)) {
            throw new EscalationException('Escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        fflib_Application.UnitOfWork uow = Application.UnitOfWork.newInstance();

        Boolean didWork = false;
        for (Case c : cases) {
            // Skip cases that are closed or already escalated.
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            Task escalationTask = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
            uow.registerNew(escalationTask);

            didWork = true;
        }

        // Only commit when at least one case actually needed escalating.
        if (didWork) {
            uow.commitWork();
        }
    }
}
