public with sharing class OpportunityWinService {

    private static final String CLOSED_WON_STAGE = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        final List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Build the set of opportunities that still need to be closed.
        final List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != CLOSED_WON_STAGE) {
                opp.StageName = CLOSED_WON_STAGE;
                opp.CloseDate = Date.today();
                opportunitiesToClose.add(opp);
            }
        }

        // Nothing to do: avoid any DML / event publishing.
        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        // A single unit of work performs the update and publishes the events,
        // committed together in one transaction.
        final fflib_IUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();
        unitOfWork.markUpdatable(opportunitiesToClose);

        // The domain is only used as the grouping key for the published events.
        final fflib_ISObjectDomain opportunityDomain =
            new fflib_SObjectDomain(new List<SObjectType>{ Opportunity.SObjectType });

        for (Opportunity opp : opportunitiesToClose) {
            unitOfWork.publish(
                opportunityDomain,
                'Deal_Won__e',
                new List<SObjectField>{ Deal_Won__e.Opportunity_Id__c, Deal_Won__e.Amount__c },
                new Deal_Won__e(
                    Opportunity_Id__c = opp.Id,
                    Amount__c = opp.Amount
                )
            );
        }

        // commitWork() runs the DML first and only publishes the registered
        // Deal_Won__e events after the updates succeed. If the DML fails the
        // exception propagates and no event is published.
        unitOfWork.commitWork();

        return opportunitiesToClose.size();
    }
}
