public class PipelineSummary {

    // The four open stages sales ops manages. Kept as a Set so we can iterate
    // cleanly; order is irrelevant because we key the result map by stage name.
    private static final Set<String> OPEN_STAGES = new Set<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Returns the summed Opportunity Amount for each of the four open stages,
     * for opportunities whose CloseDate falls between fromDate and toDate
     * (inclusive). Every stage is always present in the map, defaulting to 0
     * when there are no matching opportunities or when the SUM is null.
     * Opportunities with a null Amount are ignored by SUM() and add nothing.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : OPEN_STAGES) {
            totals.put(stage, 0);
        }

        for (String stage : OPEN_STAGES) {
            AggregateResult[] results = [
                SELECT SUM(Amount) total
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            if (results != null && !results.isEmpty()) {
                Decimal sum = (Decimal) results[0].get('total');
                if (sum != null) {
                    totals.put(stage, sum);
                }
            }
        }

        return totals;
    }
}
