public with sharing class CasePriorityHandler {

    private static final String HOT_RATING = 'Hot';
    private static final String HIGH_PRIORITY = 'High';

    /**
     * Called from CaseTrigger (before insert).
     * Sets Priority = 'High' for cases whose Account has Rating = 'Hot'.
     * Every other case (including cases with no Account) keeps its Priority.
     */
    public static void onBeforeInsert(List<Case> newCases) {
        if (newCases == null || newCases.isEmpty()) {
            return;
        }

        // Gather every AccountId referenced by the incoming cases.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        // One query for all accounts (bulk-safe), not one query per case.
        Map<Id, Account> accountsById = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accountsById = new Map<Id, Account>(
                [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
            );
        }

        // Apply the hot-account rule case by case.
        // Map.get(null) returns null, so cases without an Account are skipped safely.
        for (Case c : newCases) {
            Account acc = accountsById.get(c.AccountId);
            if (acc != null && acc.Rating == HOT_RATING) {
                c.Priority = HIGH_PRIORITY;
            }
        }
    }
}
