    // Collect the distinct accounts whose open pipeline may have changed, then
    // recalculate them in a single asynchronous, bulk-safe pass. This avoids
    // enqueueing one future job per opportunity (up to 200 per CPQ batch).
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.New) {
        // Insert: always recompute. Update: only when the pipeline picture
        // changed, i.e. StageName or Amount changed.
        Boolean pipelineChanged = Trigger.isInsert;

        if (Trigger.isUpdate) {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
            pipelineChanged = opp.StageName != oldOpp.StageName
                    || opp.Amount != oldOpp.Amount;
        }

        if (pipelineChanged && opp.AccountId != null) {
            accountIds.add(opp.AccountId);
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
