public class LineItemDiscountHandler {

    /**
     * Before insert: give each new line the standard discount for its product,
     * but only when Discount was left blank. A Discount already present on the
     * incoming line (including an explicit 0) is preserved.
     *
     * The discount RULES stay in PricingRules and are not duplicated here. We bulk
     * the Product2 lookup ourselves (one SOQL for the whole batch) and reuse
     * PricingRules.standardDiscountForFamily, so the family -> percent mapping lives
     * in exactly one place.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        if (newLines == null) {
            return;
        }

        // Only lines with a blank Discount and a product need a lookup.
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }
        if (productIds.isEmpty()) {
            return;
        }

        // One query for the whole batch instead of one per line. A single quote can
        // carry up to 200 lines in one insert; calling PricingRules.standardDiscountFor
        // per line would run up to 200 SOQL queries and exceed the 100-queries-per-
        // transaction limit.
        Map<Id, String> familyByProduct = new Map<Id, String>();
        for (Product2 product : [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]) {
            familyByProduct.put(product.Id, product.Family);
        }

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                line.Discount = PricingRules.standardDiscountForFamily(familyByProduct.get(line.Product2Id));
            }
        }
    }
}
