public with sharing class CaseSurveyJob implements Queueable {
    private final String caseId;

    public CaseSurveyJob(String caseId) {
        this.caseId = caseId;
    }

    public void execute() {
        // Re-fetch the case so this job is self-contained and independently testable.
        Case c = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        // Cases without a contact get no task.
        if (c == null || String.isBlank(c.ContactId)) {
            return;
        }

        insert new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );
    }
}
