import { LightningElement, api, wire } from 'lwc';
import getContacts from './ContactController';
import { updateRecord } from 'lightning/uiRecordApi';
import { refreshApex } from '@salesforce/apex';

// Self-contained equivalent of the standard ShowToastEvent so the component
// does not depend on an external helper file. The record-page container
// listens for the 'toast' event and renders it.
class ShowToastEvent extends CustomEvent {
    constructor({ title, message, variant }) {
        super('toast', {
            detail: { title, message, variant },
            bubbles: true,
            composed: true,
            cancelable: true
        });
    }
}

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    contacts;
    draftValues = [];
    columns = COLUMNS;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.contacts = result.data;
    }

    handleSave(event) {
        const updates = event.detail.draftValues.map((draft) =>
            updateRecord({ fields: { ...draft } })
        );

        // Run all updates in parallel and wait for every one to settle.
        Promise.allSettled(updates).then((results) => {
            const failed = results.find((result) => result.status === 'rejected');

            if (failed) {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        message: failed.reason.body.message,
                        variant: 'error'
                    })
                );
                return;
            }

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Contacts updated',
                    variant: 'success'
                })
            );

            this.draftValues = [];
            return refreshApex(this.wiredContacts);
        });
    }
}
