import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    MessageContext
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    accountId = null;
    subscription = null;

    @wire(MessageContext)
    messageContext;

    connectedCallback() {
        // Subscribe on insert. Guard ensures we never hold more than one
        // subscription (disconnectedCallback nulls it out on removal).
        if (!this.subscription) {
            this.subscription = subscribe(
                this.messageContext,
                ACCOUNT_SELECTED,
                (message) => this.handleMessage(message)
            );
        }
    }

    disconnectedCallback() {
        // Clean up so the component can re-subscribe if it is inserted again
        // later (e.g., when a tab is reopened).
        unsubscribe(this.subscription);
        this.subscription = null;
    }

    handleMessage(message) {
        // Only a non-null recordId yields a selected account; anything else
        // (including the clear message) resets to the placeholder state.
        this.accountId = message.recordId ? message.recordId : null;
    }

    handleClear() {
        // Publish a null selection so every listening component (including
        // this one) clears its current account.
        publish(this.messageContext, ACCOUNT_SELECTED, { recordId: null });
    }
}
