            deleteRecord(row.Id)
                .then(() => {
                    // Create a new array so the parent's array is not mutated.
                    this.opportunities = this.opportunities.filter(
                        (opp) => opp.Id !== row.Id
                    );
                    this.dispatchEvent(
                        new ShowToastEvent({
                            title: 'Opportunity deleted',
                            variant: 'success'
                        })
                    );
                })
                .catch((error) => {
                    this.dispatchEvent(
                        new ShowToastEvent({
                            title: 'Delete failed',
                            variant: 'error',
                            message: error.body.message
                        })
                    );
                });
        });
