```javascript
import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /**
     * Order lines to edit.
     * @type {Array<{ key: string, productName: string, quantity: number }>}
     */
    @api lines = [];

    showErrorMessage = false;

    /**
     * Line item editor child components, in display order.
     * querySelectorAll returns elements in document order, which matches
     * the for:each iteration order (i.e. the order of `lines`).
     */
    getLineEditors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    handleReset() {
        this.getLineEditors().forEach((editor) => editor.reset());
        // A reset is not a submit; per spec the error message is only
        // cleared once a later submit succeeds, so we leave it alone here.
    }

    handleSubmit() {
        const editors = this.getLineEditors();
        let allValid = true;
        const lines = [];

        // Validate every editor, even after one fails, so that all invalid
        // lines surface their errors at once (no short-circuiting).
        for (const editor of editors) {
            if (!editor.validate()) {
                allValid = false;
            }
            // Collect each line's value in display order, regardless of validity.
            lines.push(editor.getValue());
        }

        if (allValid) {
            this.showErrorMessage = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines },
                }),
            );
        } else {
            this.showErrorMessage = true;
        }
    }
