```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_MILLIS = 60000; // refresh every 60 seconds

export default class extends LightningElement {
    waiting = null;
    longestWaitMinutes = null;
    error = null;
    loaded = false;

    _refreshTimer = null;
    _isRequestInFlight = false;
    _onVisibilityChange = null;

    connectedCallback() {
        // Ignore polls while the console lives in a background tab.
        this._onVisibilityChange = this._handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._onVisibilityChange);

        // Start exactly one polling loop: load now, then refresh every 60s.
        this._clearTimer();
        this._loadStats();
        this._scheduleRefresh();
    }

    disconnectedCallback() {
        // Stop all polling and remove the listener so nothing keeps running.
        this._clearTimer();
        if (this._onVisibilityChange !== null) {
            document.removeEventListener(
                'visibilitychange',
                this._onVisibilityChange
            );
            this._onVisibilityChange = null;
        }
        // Release the in-flight latch in case a call was mid-flight on removal.
        this._isRequestInFlight = false;
    }

    _scheduleRefresh() {
        this._refreshTimer = setInterval(() => {
            // Make no requests while the page is hidden (background tab).
            if (document.visibilityState === 'hidden') {
                return;
            }
            this._loadStats();
        }, REFRESH_MILLIS);
    }

    _clearTimer() {
        if (this._refreshTimer !== null) {
            clearInterval(this._refreshTimer);
            this._refreshTimer = null;
        }
    }

    _handleVisibilityChange() {
        if (document.visibilityState !== 'visible') {
            return;
        }
        // Became visible again: load immediately and restart the 60s cadence.
        this._clearTimer();
        this._loadStats();
        this._scheduleRefresh();
    }

    async _loadStats() {
        // Never start a request while the previous one is still in flight.
        if (this._isRequestInFlight) {
            return;
        }
        this._isRequestInFlight = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.error = null;
            this.loaded = true;
        } catch (error) {
            // Keep polling; surface the message until the next success clears it.
            this.error =
                error && error.body && error.body.message
                    ? error.body.message
                    : 'Unable to load queue statistics';
        } finally {
            this._isRequestInFlight = false;
        }
    }
}
