import { LightningElement, api } from 'lwc';

// Keys that move the active option (bounded, no wrap-around).
const MOVING_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End']);

// Keys that select the active option.
const SELECT_KEYS = new Set(['Enter', ' ']);

// Every key this widget intercepts. Any other key (notably Tab) is left
// untouched so its default behaviour is preserved.
const HANDLED_KEYS = new Set([...MOVING_KEYS, ...SELECT_KEYS]);

const OPTION_ID_PREFIX = 'status-listbox-option';

/**
 * A single-select listbox that follows the WAI-ARIA listbox pattern using
 * aria-activedescendant. DOM focus stays on the list (<ul>); the "active"
 * option is only referenced, never focused.
 */
export default class StatusListbox extends LightningElement {
    /** Accessible name of the list, used as aria-label. */
    @api label = '';

    /** Selectable options, each shaped like { value, label }. */
    @api options = [];

    /** Currently selected value; may be empty. */
    @api value = '';

    /**
     * Index of the active option. This is keyboard state that is independent
     * of the selection: moving the active option never changes the value.
     */
    _activeIndex = 0;

    // Seed the active option from the initial selection before first render.
    connectedCallback() {
        this._syncActiveToValue();
    }

    // Keep the active option aligned with the selection whenever the parent
    // changes `value` at any time.
    valueChanged() {
        this._syncActiveToValue();
    }

    _syncActiveToValue() {
        const options = this._normalizedOptions;
        const index = options.findIndex((option) => option.value === this.value);
        this._activeIndex = index >= 0 ? index : 0;
    }

    /** Options with a stable id and their selected state, ready for the template. */
    get displayOptions() {
        const selectedValue = this.value;
        return this._normalizedOptions.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `${OPTION_ID_PREFIX}-${index}`,
            ariaSelected: option.value === selectedValue ? 'true' : 'false'
        }));
    }

    /** Number of options, used to clamp the active index at the boundaries. */
    get optionCount() {
        return this._normalizedOptions.length;
    }

    /** id of the active option, referenced by aria-activedescendant. */
    get activeId() {
        const count = this.optionCount;
        if (count === 0) {
            return undefined;
        }
        const index = Math.min(Math.max(this._activeIndex, 0), count - 1);
        return `${OPTION_ID_PREFIX}-${index}`;
    }

    /**
     * Intercept only the six widget keys and prevent their default action.
     * Every other key (notably Tab) returns early so focus can move normally.
     */
    handleKeydown(event) {
        if (!HANDLED_KEYS.has(event.key)) {
            return;
        }
        event.preventDefault();

        const count = this.optionCount;
        if (count === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(this._activeIndex + 1, count - 1);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = count - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectActive();
                break;
            default:
                break;
        }
    }

    /**
     * Select the active option. Dispatches a `change` event carrying
     * `detail.value`, unless that option is already the selected one.
     */
    _selectActive() {
        const options = this._normalizedOptions;
        const index = Math.min(Math.max(this._activeIndex, 0), options.length - 1);
        const option = options[index];
        if (!option || option.value === this.value) {
            return;
        }
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
                bubbles: true,
                composed: true
            })
        );
    }

    /** Clicking an option makes it the active option and selects it. */
    handleClick(event) {
        const value = event.currentTarget.dataset.value;
        const index = this._normalizedOptions.findIndex(
            (option) => option.value === value
        );
        if (index < 0) {
            return;
        }
        this._activeIndex = index;
        this._selectActive();
    }

    /** Defensive normalisation of the public `options` array. */
    get _normalizedOptions() {
        return Array.isArray(this.options) ? this.options : [];
    }
}
