import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value;
        // Work on our own copy: never mutate the parent's array or task objects.
        this.items = Array.isArray(value) ? value.map((task) => ({ ...task })) : [];
    }

    // Display only: upper-case the heading without mutating the public value,
    // so the parent's value stays intact and later changes are reflected.
    get displayHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel.trim();
        if (!label) {
            return;
        }
        this.items = [...this.items, { id: `new-${this.nextId++}`, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(
            new CustomEvent('taskadded', { detail: { label }, bubbles: true, composed: true })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        const checked = event.target.checked;
        // Rebuild immutably so reactivity fires and the parent is never mutated.
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: checked } : task
        );
    }
}
