```apex
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces every General Accounting Unit (GAU) allocation on an opportunity
     * with one allocation per entry in percentByGauId.
     *
     * Only npsp__Percent__c is written to each allocation. NPSP derives
     * npsp__Amount__c from the percent and the opportunity amount and recalculates
     * those amounts whenever the opportunity amount changes. This keeps the
     * allocations correct after an amount correction with no extra code (e.g. a
     * $1,000 gift split 60/40 becomes $1,200/$800 when the gift is corrected to
     * $2,000).
     *
     * All validation runs before any data is changed. An AllocationException is
     * thrown when:
     *   - percentByGauId is null or empty,
     *   - any percentage is null or not greater than 0,
     *   - the percentages total more than 100 (totals below 100 are allowed; the
     *     remainder simply stays unallocated), or
     *   - any GAU is missing or inactive.
     *
     * @param opportunityId    Opportunity whose GAU allocations are being set.
     * @param percentByGauId   Map keyed by npsp__General_Accounting_Unit__c Id,
     *                         valued with the allocation percentage (60 = 60%).
     * @return                 The GAU allocations that were inserted.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId) {

        // --- Validation 1: the map must contain at least one entry ---
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException();
        }

        // --- Validation 2 & 3: each percentage is > 0, and the total is <= 100 ---
        Decimal totalPercent = 0;
        for (Decimal percent : percentByGauId.values()) {
            if (percent == null || percent <= 0) {
                throw new AllocationException();
            }
            totalPercent += percent;
        }
        if (totalPercent > 100) {
            throw new AllocationException();
        }

        // --- Validation 4: every GAU must exist and be active ---
        Map<Id, npsp__General_Accounting_Unit__c> gauById = [
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
        ];
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null || !Boolean.valueOf(gau.npsp__Active__c)) {
                throw new AllocationException();
            }
        }

        // --- Replace existing allocations (only after all validation has passed) ---
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> allocationsToInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            allocationsToInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        insert allocationsToInsert;

        return allocationsToInsert;
    }
}
