public with sharing class DiscountApprovalService {

    /**
     * Decides whether the running user may approve the given discount.
     *
     * @param  discountPercent the requested discount, as a percentage (e.g. 15 = 15%)
     * @return false for a null or negative value;
     *         true for 0 up to and including 15;
     *         for anything above 15, whether the running user holds the
     *         Approve_Large_Discount custom permission.
     */
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        // Null or negative discounts can never be approved.
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }

        // Discounts from 0 up to and including 15% are within the standard limit.
        if (discountPercent <= 15) {
            return true;
        }

        // Anything above 15% requires the custom permission, regardless of which
        // permission set or permission set group granted it.
        return User.hasPermission('Approve_Large_Discount');
    }
}
