/*
 * AccountOwnershipService
 *
 * Moves a book of business from one sales rep to another by reassigning
 * ownership of the affected Accounts and every Contact on those Accounts.
 *
 * Behaviour:
 *   - The Account sObject is bypassed through the Trigger Actions Framework
 *     (TriggerBase) for the whole method, so NONE of the (expensive,
 *     territory-recalculating) Account trigger actions run for this ownership
 *     change.
 *   - Contacts are updated normally, so every registered Contact trigger
 *     action runs.
 *   - The Account bypass is always released in a finally block, so once this
 *     method returns -- whether it completed or threw -- Account automation
 *     behaves normally for the remainder of the transaction.
 *   - Keyword DML is all-or-none, so any DmlException propagates to the caller
 *     unchanged and the entire reassignment rolls back as a single unit.
 *   - Bulk-safe: no more than one SOQL query and two DML statements are issued
 *     regardless of volume (callers may pass up to 200 Accounts). Accounts are
 *     rebuilt from the supplied ids, so no query is needed for them.
 */
public with sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Suppress ALL Account trigger actions for this ownership change.
        TriggerBase.bypass(Schema.SObjectType.Account);
        try {
            if (accountIds != null && !accountIds.isEmpty()) {
                // Reassign the Accounts without querying them (build from the ids).
                List<Account> accountsToReassign = new List<Account>();
                for (Id accountId : accountIds) {
                    accountsToReassign.add(new Account(Id = accountId, OwnerId = newOwnerId));
                }
                update accountsToReassign;

                // Reassign every Contact on those Accounts; Contact automation runs normally.
                List<Contact> contactsToReassign = [
                    SELECT Id
                    FROM Contact
                    WHERE AccountId IN :accountIds
                ];
                for (Contact c : contactsToReassign) {
                    c.OwnerId = newOwnerId;
                }
                if (!contactsToReassign.isEmpty()) {
                    update contactsToReassign;
                }
            }
        } finally {
            // Always restore normal Account automation for the rest of the transaction.
            TriggerBase.clearBypass(Schema.SObjectType.Account);
        }
    }
}
