public class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact c : triggerNew) {
            if (c.AccountId == null) {
                continue;
            }

            if (!String.isBlank(c.LeadSource)) {
                continue;
            }

            Account parentAccount = accountsById.get(c.AccountId);
            if (parentAccount != null && parentAccount.AccountSource != null) {
                c.LeadSource = parentAccount.AccountSource;
            }
        }
    }
}
